args.script:
"const resp = await page.goto('http://localhost:5173/');
await page.screenshot();
return {
  url: page.url(),
  title: await page.title(),
  status: resp.status()
};"

"const resp = await page.goto('http://localhost:5173/', { waitUntil: 'domcontentloaded' });
const title = await page.title();
const url = page.url();
const bodyText = await page.locator('body').innerText();
await page.screenshot();
return { url, title, bodySnippet: bodyText.slice(0, 500) };"

"await page.setViewportSize({ width: 1440, height: 950 });
// Let's check for board elements or svg or canvas
const boardHtml = await page.locator('main').innerHTML();
return {
  viewport: await page.viewportSize(),
  boardHtmlSnippet: boardHtml.slice(0, 1000)
};"

"const centerCol = await page.locator('main .lg\\:col-span-6').or(page.locator('main > div > div:nth-child(2)')).innerHTML();
return {
  centerColSnippet: centerCol.slice(0, 1500)
};"

"const page2 = await page.context().newPage();
await page2.goto('http://localhost:5173/src/components/board/ChessboardContainer.tsx');
const content = await page2.locator('body').innerText();
await page2.close();
return {
  contentSnippet: content.slice(0, 2000)
};"
